  guideSlug: "tv-mount-types-explained",
  guideTitle: "TV Mount Types Explained: Fixed, Tilt and Full Motion",
  metaTitle: "TV Mount Types Explained: Fixed, Tilt, Swivel",
  metaDescription: "Fixed, tilting and full-motion TV mounts compared, with VESA patterns, weight ratings, wall depth when extended and stud spacing for a safe install.",
  heroImage: "/images/articles/tvmount-wall-panel-room.webp",
